#include <iostream>
using namespace std;
int x,y,r,j,l,h,px,py,i,o;
int main(){cout<<"ROBOTRON\n";cout<<"X:";cin>>x;cout<<"Y:";cin>>y;cout<<"R:";cin>>r;cout<<"J:";cin>>j;if((x*y)<(r+j+1)){cout<<"SCREEN TOO SMALL!"<<endl;return 1;}cout<<"L:";cin>>l;cout<<"H:";cin>>h;px=x/2;py=y/2;char* screen=new char[x*y];char* screen2=new char[x*y];memset(screen,' ',x*y);screen[px+(py*x)]='@';while(i<r){int rx=rand()%x;int ry=rand()%y;(screen[rx+(ry*x)]==' ')?screen[rx+(ry*x)]='#':i--;i++;}i=0;while(i<j){int jx=rand()%x;int jy=rand()%y;(screen[jx+(jy*x)]==' ')?screen[jx+(jy*x)]='^':i--;i++;}while(l>0&&r>0){system("cls");i=0;while(i<y){o=0;while(o<x){cout<<screen[o+(i*x)];o++;}cout<<endl;i++;}cout<<"Lives: "<<l<<" Robots: "<<r<<" Hyperspace: "<<h<<endl;memset(screen2,' ',x*y);char input;cin>>input;int new_px=px,new_py=py;switch(input){case'w':new_py--;break;case's':new_py++;break;case'a':new_px--;break;case'd':new_px++;break;case'h':{if(!h)continue;while(screen[new_px+(new_py*x)]!=' '&&h>0)new_px=rand()%x,new_py=rand()%y;;h--;break;}default:continue;}if(new_px<0||new_px>=x||new_py<0||new_py>=y)continue;screen[px+(py*x)]=' ';(screen[new_px+(new_py*x)]=='#')?l--,screen[new_px+(new_py*x)]='@',screen2[new_px+(new_py*x)]='@',px=new_px,py=new_py:screen[new_px+(new_py*x)]='@',screen2[new_px+(new_py*x)]='@',px=new_px,py=new_py;i=0;while(i<y){o=0;while(o<x){int lc=o+(i*x);if(screen[lc]=='#'){int move_x=0, move_y=0;if(o>px)move_x=-1;else if(o<px)move_x=1;if(i>py)move_y=-1;else if(i<py)move_y=1;int new_rx=o+move_x;int new_ry=i+move_y;screen[o+(i*x)]=' ';if(screen2[new_rx+(new_ry*x)]=='@')l--;else if(screen[new_rx+(new_ry*x)]=='^'||screen2[new_rx+(new_ry*x)]=='#')screen2[new_rx+(new_ry*x)]='^';else screen2[new_rx+(new_ry*x)]='#';}else if(screen[lc]=='^')screen2[lc]=screen[lc];o++;}i++;}r=0;while(i<x*y){if(screen2[i]=='#')r++;i++;}char* temp=screen;screen=screen2;screen2=temp;}if(!r){cout<<"You win!"<<endl;}else if(!l){cout<<"You lose!"<<endl;}cout<<"Game Over!"<<endl;delete[] screen;delete[] screen2;}
